<?php
namespace App\Services;use App\Models\Committee;
class CommitteeIndicatorService{public function calculate(Committee $committee):array{$applicable=$committee->scheduleItems()->whereNotIn('status',['cancelled'])->count();$completed=$committee->scheduleItems()->where('status','completed')->count();$meetingsProgrammed=$committee->scheduleItems()->whereIn('activity_type',['ordinary_meeting','extraordinary_meeting'])->whereNotIn('status',['cancelled'])->count();$meetingsDone=$committee->meetings()->whereIn('status',['minutes_draft','minutes_review','closed'])->count();$minutesFinal=\App\Models\CommitteeMinute::whereHas('meeting',fn($q)=>$q->where('committee_id',$committee->id))->where('status','final')->count();$commitments=$committee->commitments()->count();$completedCommitments=$committee->commitments()->where('status','completed')->count();$overdue=$committee->commitments()->whereDate('due_date','<',today())->whereNotIn('status',['completed','cancelled'])->count();$attendance=\App\Models\CommitteeMeetingAttendee::whereHas('member',fn($q)=>$q->whereHas('period',fn($p)=>$p->where('committee_id',$committee->id)))->count();$validAttendance=\App\Models\CommitteeMeetingAttendee::whereHas('member',fn($q)=>$q->whereHas('period',fn($p)=>$p->where('committee_id',$committee->id)))->whereIn('attendance_status',['present','replacement'])->count();return['schedule_execution'=>$this->percent($completed,$applicable),'meetings_execution'=>$this->percent($meetingsDone,$meetingsProgrammed),'minutes_closed'=>$this->percent($minutesFinal,$meetingsDone),'commitments_completed'=>$this->percent($completedCommitments,$commitments),'overdue_commitments'=>$overdue,'participation'=>$this->percent($validAttendance,$attendance),'meetings_done'=>$meetingsDone,'meetings_programmed'=>$meetingsProgrammed,'commitments_total'=>$commitments];}public function signal(?float $value):array{if($value===null)return['label'=>'Sin datos','class'=>'secondary'];$adequate=config('committees.indicators.adequate',85);$attention=config('committees.indicators.attention',60);return$value>=$adequate?['label'=>'Adecuado','class'=>'success']:($value>=$attention?['label'=>'Atención','class'=>'warning']:['label'=>'Crítico','class'=>'danger']);}private function percent(int $part,int $total):?float{return$total?round($part/$total*100,1):null;}}
